sap.ui.define([], function () {
	"use strict";

	// The texts of the page in German, English and Russian. They live in i18n/i18n_<lang>.properties; this module
	// reads the three files and hands them out as TEXT[lang] in the form the page code uses (t.carsH, t.xl.title,
	// t.rules[0], t.tickets(n), t.chk.emptyCar({ n: 1 }) ...). The language is switched inside the page (DE / EN / RU
	// buttons), independent of the logon language, which is why all three are loaded.
	//
	// GENERATED by tools/gen-i18n.mjs (SHAPE below and the i18n files) - change tools/text.template.js, not this file.

	var LANGS = ["de", "en", "ru"];
	var TEXT = {}; // TEXT.de / .en / .ru, filled by load()
	var EXTRA = {}; // texts only the Fiori version needs (saving in the SAP system)

	// the keys of TEXT[lang] in their order: [name] text, [name, n] list of n texts ("name.0" ...),
	// [name, [keys]] group ("name.key"), [name, "f"] made by FN below
	var SHAPE = [
		["title"],
		["sub"],
		["demo"],
		["leg"],
		["date"],
		["depart"],
		["oclock"],
		["navCars"],
		["navTram"],
		["navTaxi"],
		["navAll"],
		["navChecks"],
		["navCards"],
		["menu"],
		["plannerMenu"],
		["goTo"],
		["persons"],
		["away"],
		["byCar"],
		["byTram"],
		["byTaxi"],
		["restBy"],
		["export"],
		["carsH"],
		["carsSub"],
		["dragHint"],
		["picked"],
		["cancel"],
		["car"],
		["driver"],
		["free"],
		["noCars"],
		["tramH"],
		["tramSub", "f"],
		["moveHint"],
		["group"],
		["buyer"],
		["makeBuyer"],
		["tickets", "f"],
		["groupSize"],
		["groupCount"],
		["taxiSize"],
		["addGroup"],
		["addTaxi"],
		["removeBox"],
		["taxiH"],
		["taxiSub"],
		["taxi"],
		["nothing"],
		["allH"],
		["allSub"],
		["csvHint"],
		["count"],
		["addPh"],
		["noMatch", "f"],
		["add"],
		["load"],
		["reset"],
		["removeAsk", "f"],
		["resetAsk"],
		["replaceAsk", "f"],
		["csvEmpty"],
		["remove"],
		["seatsOf"],
		["mode"],
		["assign"],
		["name"],
		["filterAll"],
		["filterAway"],
		["ruleH"],
		["ruleSub"],
		["rules", 4],
		["darkH", "f"],
		["rights"],
		["csvHead", 10],
		["xl", ["title", "overview", "people", "level", "check", "checkCol", "messages", "costs", "ticketPrice", "taxiPrice", "adjust", "tickets", "rides", "ticketCost", "taxiCost", "total", "sum"]],
		["notThere"],
		["optionsLabel"],
		["groupBy"],
		["groupNone"],
		["groupTeam"],
		["groupLang"],
		["team"],
		["langCol"],
		["undo"],
		["redo"],
		["savePlan"],
		["loadPlan"],
		["planSaved"],
		["planBad"],
		["planAsk"],
		["planHint"],
		["checksH"],
		["checksSub"],
		["noIssues"],
		["rulesH"],
		["rulesSub"],
		["addRule"],
		["rulesBtn"],
		["departAt"],
		["exportFailed"],
		["noRules"],
		["ruleTypes", ["pair", "lang", "teamMax", "person", "note"]],
		["pairWith"],
		["pairTogether"],
		["pairApart"],
		["ruleLangA"],
		["ruleTeamA"],
		["ruleTeamB"],
		["allTeams"],
		["personNoTaxi"],
		["personNoTram"],
		["personInCar"],
		["personNotAlone"],
		["noteCol"],
		["keyword"],
		["noteRuleA"],
		["copyLeg2"],
		["copyLegTip"],
		["legCopied"],
		["pickPerson"],
		["levelWarn"],
		["levelInfo"],
		["levelToggle"],
		["ruleOn"],
		["ruleActive"],
		["ruleInactive"],
		["ruleRemove"],
		["legWord"],
		["kinds", ["car", "group", "taxi", "team", "lang"]],
		["chk", "f"],
		["cardsH"],
		["cardsSub"],
		["copy"],
		["copied"],
		["copyLeg"],
		["passengers"],
		["members"],
		["all"],
		["layout"],
		["layoutH"],
		["layoutHint"],
		["variants"],
		["defaultVariant"],
		["editOrder"],
		["saveNewVariant"],
		["updateVariant"],
		["deleteVariant"],
		["resetLayout"],
		["variantName"],
		["variant"],
		["variantSaved"],
		["variantDeleteAsk", "f"],
		["changed"],
		["undoOrder"],
		["rename"],
		["save"],
		["newVariant"],
		["done"],
		["close"],
		["segTram"],
		["segTaxi"],
		["foldOpen"],
		["foldClose"],
		["up"],
		["down"],
		["sections", ["leg", "plan", "counts", "checks", "cars", "tram", "taxi", "people", "cards"]]
	];

	// "{0} of {1}" + [2, 5] -> "2 of 5" (done here, not by the UI5 formatter: no quote escaping rules in the files)
	function fill(sPattern, aArgs) {
		return String(sPattern).replace(/\{(\d+)\}/g, function (sAll, sIndex) {
			return Number(sIndex) < aArgs.length ? String(aArgs[Number(sIndex)]) : sAll;
		});
	}

	// texts that depend on values; g(key) reads a text, g(key, [args]) fills its pattern
	var FN = {
		tramSub: function (g) { return function (from) { return g("tramSub", [from]); }; },
		tickets: function (g) { return function (n) { return g(n === 1 ? "tickets.one" : "tickets.other", [n]); }; },
		noMatch: function (g) { return function (n) { return g("noMatch", [n]); }; },
		removeAsk: function (g) { return function (n) { return g("removeAsk", [n]); }; },
		replaceAsk: function (g) { return function (n) { return g("replaceAsk", [n]); }; },
		darkH: function (g) { return function (n) { return g("darkH", [n]); }; },
		variantDeleteAsk: function (g) { return function (n) { return g("variantDeleteAsk", [n]); }; },
		chk: function (g) {
			var RULES = ["noTaxi", "noTram", "inCar", "notAlone"];
			return {
				noPeople: function () { return g("chk.noPeople"); },
				rule: function (a) {
					var bKnown = RULES.indexOf(a.rule) !== -1;
					switch (a.type) {
						case "pair": return g(a.mode === "together" ? "chk.rule.pair.together" : "chk.rule.pair.apart", [a.a, a.b]);
						case "lang": return g("chk.rule.lang", [a.bad, a.total, a.lang]);
						case "teamMax": return g("chk.rule.teamMax." + (a.max === 1 ? "one" : "other") + "." + (a.team === "*" ? "all" : "team"), [a.bad, a.max, a.team]);
						case "note": return g("chk.rule.note", [a.keyword, a.names, bKnown ? g("chk.rule.note." + a.rule) : undefined]);
						case "person": return bKnown ? g("chk.rule.person." + a.rule, [a.name]) : undefined;
						default: return undefined;
					}
				},
				emptyCar: function (p) { return g("chk.emptyCar", [p.n]); },
				freeSeats: function (p) { return g("chk.freeSeats", [p.free, p.others]); },
				smallGroup: function (p) { return g(p.size === 1 ? "chk.smallGroup.one" : "chk.smallGroup.other", [p.n, p.size]); },
				lonelyTaxi: function (p) { return g("chk.lonelyTaxi", [p.n]); },
				emptyBox: function (p) { return g(p.kind === "group" ? "chk.emptyBox.group" : "chk.emptyBox.taxi", [p.n]); },
				mixed: function (p, k) { return g("chk.mixed", [p.count, p.total, k[p.by]]); },
				carNotThere: function (p) { return g("chk.carNotThere", [p.name]); }
			};
		}
	};

	function buildExtra(g) {
		return {
			loading: g("x.loading"),
			saving: g("x.saving"),
			saved: function (sTime) { return sTime ? g("x.saved.at", [sTime]) : g("x.saved"); },
			savedTitle: function (sBy, sAt) { return !sBy ? g("x.savedTitle") : sAt ? g("x.savedTitle.byAt", [sBy, sAt]) : g("x.savedTitle.by", [sBy]); },
			unsaved: g("x.unsaved"),
			local: g("x.local"),
			localTitle: g("x.localTitle"),
			error: g("x.error"),
			conflictH: g("x.conflictH"),
			conflictText: function (sBy, sAt) { return sAt ? g("x.conflictText.at", [sBy || g("x.someone"), sAt]) : g("x.conflictText", [sBy || g("x.someone")]); },
			conflictReload: g("x.conflictReload"),
			conflictOverwrite: g("x.conflictOverwrite"),
			appTitle: g("appTitle")
		};
	}

	// take the texts of one language; fnRaw(key) returns the text of the i18n file as it is
	function use(sLang, fnRaw) {
		var g = function (sKey, aArgs) {
			return aArgs ? fill(fnRaw(sKey), aArgs) : fnRaw(sKey);
		};
		var t = {};
		SHAPE.forEach(function (aEntry) {
			var sName = aEntry[0];
			var vKind = aEntry[1];
			if (vKind === undefined) {
				t[sName] = g(sName);
			} else if (vKind === "f") {
				t[sName] = FN[sName](g);
			} else if (typeof vKind === "number") {
				t[sName] = [];
				for (var i = 0; i < vKind; i++) {
					t[sName].push(g(sName + "." + i));
				}
			} else {
				t[sName] = {};
				vKind.forEach(function (sSub) {
					t[sName][sSub] = g(sName + "." + sSub);
				});
			}
		});
		TEXT[sLang] = t;
		EXTRA[sLang] = buildExtra(g);
	}

	// read i18n_de / _en / _ru; the Promise resolves when TEXT and EXTRA are filled
	function load() {
		return new Promise(function (resolve, reject) {
			sap.ui.require(["sap/base/i18n/ResourceBundle"], function (ResourceBundle) {
				var sUrl = sap.ui.require.toUrl("com/alseda/carpool/i18n/i18n.properties");
				Promise.all(LANGS.map(function (sLang) {
					return ResourceBundle.create({ url: sUrl, locale: sLang, async: true }).then(function (oBundle) {
						use(sLang, function (sKey) {
							return oBundle.getText(sKey);
						});
					});
				})).then(resolve, reject);
			}, reject);
		});
	}

	return {
		TEXT: TEXT,
		EXTRA: EXTRA,
		LANGS: LANGS,
		load: load,
		use: use
	};
});
